def last_Digit_Factorial(n):
    """
    Finds the last digit in the factorial of a given number n.

    For n >= 5, the factorial will always contain at least one factor of 2 
    and one factor of 5 (since 5! = 120), which means the product will 
    always end in 0.
    """
    if n == 0:
        return 1
    elif n == 1:
        return 1
    elif n == 2:
        return 2
    elif n == 3:
        return 6
    elif n == 4:
        return 4
    else:
        return 0

# Test the function with the provided assertion
assert last_Digit_Factorial(4) == 4
